-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.deed_trade_workers(p_world uuid, p_keeper uuid, p_kind text)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE
AS $function$
begin
  return (
select count(*)::int
    from deed_people(p_world, p_keeper) k(uid)
    join creature c on c.world_id = p_world and c.keeper = k.uid
    join species_def sd on sd.id = c.species
   where c.mode = 'deed' and coalesce(c.job, sd.gathers) = p_kind
  );
end $function$
